<?php
namespace Certloom\Infrastructure\Admin;

use Certloom\Application\Integration\IntegrationFieldCompatibility;
use Certloom\Application\Templates\TemplateFieldCompatibility;
use Certloom\Infrastructure\Integration\WebhookSourceRepository;
use Certloom\Infrastructure\Repository\ProgramRepository;
use Certloom\Infrastructure\Repository\TemplateRepository;

if ( ! defined( 'ABSPATH' ) ) { exit; }

/** Human admin boundary for generic signed completion webhooks. */
final class WebhookIntegrationAdmin {
	const SECRET_TRANSIENT_PREFIX = 'certloom_webhook_setup_secret_';
	public function register(){add_action('admin_post_certloom_webhook_source_create',array($this,'create'));add_action('admin_post_certloom_webhook_secret_rotate',array($this,'rotate'));add_action('admin_post_certloom_webhook_source_delete',array($this,'delete'));}
	/** @return array<string,mixed> */
	public function screen_data(){ $sources=(new WebhookSourceRepository())->all();foreach($sources as &$source){$source['endpoint']=rest_url('certloom/v1/integrations/webhook/'.(string)$source['key']);}unset($source);$data=array('sources'=>$sources,'programs'=>array(),'templates'=>array(),'configuration_ready'=>false,'one_time_secret'=>$this->pull_secret(),'error'=>null);if(!\Certloom\Infrastructure\Migration\DomainFeatureGate::admin_preview_ready())return$data;$programs=(new ScopedContextChoices())->programs();$templates=(new ScopedContextChoices())->templates();if(is_wp_error($programs)){$data['error']=$programs;return$data;}if(is_wp_error($templates)){$data['error']=$templates;return$data;}$data['programs']=(array)$programs;$data['templates']=(array)$templates;$data['configuration_ready']=true;return$data;}
	public function create(){ $this->cap();check_admin_referer('certloom_webhook_source_create');if(!\Certloom\Infrastructure\Migration\DomainFeatureGate::admin_preview_ready())$this->redirect(new \WP_Error('certloom_webhook_preview_closed',__('Webhook setup is unavailable until the Certloom Program and design workflow is available.','certloom')));$name=isset($_POST['name'])?sanitize_text_field(wp_unslash($_POST['name'])):'';$program=isset($_POST['program_id'])?absint($_POST['program_id']):0;$template=isset($_POST['template_id'])?absint($_POST['template_id']):0;$valid=$this->validate_mapping($program,$template);if(is_wp_error($valid))$this->redirect($valid);$result=(new WebhookSourceRepository())->create(array('name'=>$name,'program_id'=>$program,'template_id'=>$template,'active'=>true));if(is_wp_error($result))$this->redirect($result);if(!$this->store_secret($result)){(new WebhookSourceRepository())->delete($result['key']);$this->redirect(new \WP_Error('certloom_webhook_secret_display_failed',__('Certloom generated the webhook secret but could not keep it long enough to show it safely. The source was removed; please try again.','certloom')));}$this->redirect(true,'webhook_source_created');}
	public function rotate(){ $this->cap();$key=isset($_POST['source_key'])?sanitize_key(wp_unslash($_POST['source_key'])):'';check_admin_referer('certloom_webhook_secret_rotate_'.$key);$result=(new WebhookSourceRepository())->rotate($key);if(is_wp_error($result))$this->redirect($result);if(!$this->store_secret($result))$this->redirect(new \WP_Error('certloom_webhook_secret_display_failed',__('Certloom rotated the webhook secret but could not display it. Rotate it again before sending another webhook.','certloom')));$this->redirect(true,'webhook_secret_rotated');}
	public function delete(){ $this->cap();$key=isset($_POST['source_key'])?sanitize_key(wp_unslash($_POST['source_key'])):'';check_admin_referer('certloom_webhook_source_delete_'.$key);$this->redirect((new WebhookSourceRepository())->delete($key),'webhook_source_deleted');}
	/** @return true|\WP_Error */ private function validate_mapping($program_id,$template_id){$program=(new ProgramRepository())->find($program_id);if(is_wp_error($program)||!is_array($program)||empty($program['active']))return is_wp_error($program)?$program:new \WP_Error('certloom_webhook_program_invalid',__('Choose an active Certloom Program.','certloom'));$catalog=class_exists('\Ecapla_CertVerify_Fields')?\Ecapla_CertVerify_Fields::get_field_map():array();$fields=(new IntegrationFieldCompatibility())->validate_program($program,$catalog);if(is_wp_error($fields))return$fields;$template=(new TemplateRepository())->find_published($template_id);if(is_wp_error($template)||!is_array($template))return is_wp_error($template)?$template:new \WP_Error('certloom_webhook_template_invalid',__('Choose a published Certloom design.','certloom'));$compat=(new TemplateFieldCompatibility())->validate((array)($template['published_revision']['layout']??array()),$program,null,$catalog);return is_wp_error($compat)?$compat:true;}
	private function store_secret(array$value){return set_transient(self::SECRET_TRANSIENT_PREFIX.get_current_user_id(),$value,10*MINUTE_IN_SECONDS);}
	/** @return array<string,string> */ private function pull_secret(){if(!function_exists('get_current_user_id'))return array();$key=self::SECRET_TRANSIENT_PREFIX.get_current_user_id();$value=get_transient($key);delete_transient($key);return is_array($value)&&!empty($value['key'])&&!empty($value['secret'])?array('key'=>(string)$value['key'],'secret'=>(string)$value['secret']):array();}
	private function cap(){if(!current_user_can(\Ecapla_CertVerify_Permissions::CAP_MANAGE_INTEGRATIONS))wp_die(esc_html__('You do not have permission to manage Certloom integrations.','certloom'));}
	private function redirect($result,$notice=''){$url=admin_url('admin.php?page=certloom-integrations#certloom-webhook-setup');if(is_wp_error($result))$url=add_query_arg('certloom_error',$result->get_error_message(),$url);elseif(''!==$notice)$url=add_query_arg('certloom_notice',sanitize_key($notice),$url);wp_safe_redirect($url);exit;}
}
